#!/usr/bin/env python3

from __future__ import annotations

import hashlib
import json
import os
import subprocess
from pathlib import Path
from typing import Any

from tools import klean_export, pipeline_contract
from tools.k_rule_inventory import inventory_verification
from tools.klean_preflight import check_generation


OUTPUT = Path("/audit-output/evidence")
STAGE1 = Path("/reference/k-proof")
DISCOVERY = Path("/reference/lemma-discovery.json")
GENERATION = Path("/reference/klean-generation")
GENERATED = GENERATION / "generated"
CANDIDATE = Path("/candidate")
AUDIT_INPUT = Path("/audit-input.json")


def dump(name: str, document: Any) -> None:
    (OUTPUT / name).write_text(
        json.dumps(document, indent=2, sort_keys=True) + "\n"
    )


def sha256_file(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


audit = json.loads(AUDIT_INPUT.read_text())["resolution"]
recorded_hashes = audit["hashes"]
observed_hashes = {
    "k_workspace_sha256": pipeline_contract.sha256_tree(STAGE1),
    "stage1_export_sha256": klean_export.tree_digest(STAGE1),
    "discovery_manifest_sha256": sha256_file(DISCOVERY),
    "k_audit_sha256": pipeline_contract.sha256_tree(
        Path("/reference/k-audit")
    ),
    "klean_generation_sha256": pipeline_contract.sha256_tree(GENERATION),
    "generation_producer_sources_sha256": pipeline_contract.sha256_tree(
        Path("/reference/generation-tools")
    ),
    "generated_tree_sha256": klean_export.tree_digest(GENERATED),
    "lean_workspace_sha256": pipeline_contract.sha256_tree(CANDIDATE),
}
hash_checks = {
    key: {
        "expected": recorded_hashes[key],
        "observed": value,
        "match": recorded_hashes[key] == value,
    }
    for key, value in observed_hashes.items()
}
hash_checks["lean_invocation_sha256"] = {
    "expected": recorded_hashes["lean_invocation_sha256"],
    "observed": None,
    "match": None,
    "note": (
        "The launcher did not mount the recorded Stage 5 invocation; "
        "the declared audit input set provides /candidate as the Stage 5 "
        "workspace only."
    ),
}

recorded_stage1 = audit["stage1_source_hashes"]
observed_stage1 = {
    path.relative_to(STAGE1).as_posix(): sha256_file(path)
    for path in sorted(STAGE1.rglob("*"))
    if path.is_file() and not path.is_symlink()
}
hash_checks["stage1_source_hashes"] = {
    "expected_count": len(recorded_stage1),
    "observed_count": len(observed_stage1),
    "match": recorded_stage1 == observed_stage1,
    "missing": sorted(set(recorded_stage1) - set(observed_stage1)),
    "extra": sorted(set(observed_stage1) - set(recorded_stage1)),
    "changed": [
        key
        for key in sorted(set(recorded_stage1) & set(observed_stage1))
        if recorded_stage1[key] != observed_stage1[key]
    ],
}
dump("hash-verification.json", hash_checks)

inventory = inventory_verification(STAGE1)
dump("inventory-reconstruction.json", inventory)

discovery = json.loads(DISCOVERY.read_text())
inventory_ids = [rule["source_rule_id"] for rule in inventory["rules"]]
discovery_ids = [rule["source_rule_id"] for rule in discovery["rules"]]
dump(
    "inventory-bijection.json",
    {
        "inventory_sha256_reconstructed": inventory["inventory_sha256"],
        "inventory_sha256_protected": discovery["inventory_sha256"],
        "hash_match": (
            inventory["inventory_sha256"] == discovery["inventory_sha256"]
        ),
        "reconstructed_count": len(inventory_ids),
        "protected_count": len(discovery_ids),
        "ordered_identities_match": inventory_ids == discovery_ids,
        "duplicate_reconstructed_ids": (
            len(inventory_ids) != len(set(inventory_ids))
        ),
        "duplicate_protected_ids": (
            len(discovery_ids) != len(set(discovery_ids))
        ),
        "omitted_from_protected": sorted(
            set(inventory_ids) - set(discovery_ids)
        ),
        "extra_in_protected": sorted(
            set(discovery_ids) - set(inventory_ids)
        ),
    },
)

producer_manifest = json.loads(
    Path("/reference/generation-tools/source-manifest.json").read_text()
)
generator_manifest = json.loads(
    (GENERATION / "generator-manifest.json").read_text()
)
producer_observed = {
    "klean_export.py": sha256_file(
        Path("/reference/generation-tools/klean_export.py")
    ),
    "klean.py": sha256_file(Path("/reference/generation-tools/klean.py")),
}
recorded_source_path = Path(audit["generation_producer_sources"])
recorded_image_id = f"sha256:{recorded_source_path.name}"
dump(
    "producer-provenance.json",
    {
        "observed_files": producer_observed,
        "source_manifest_files": producer_manifest["files"],
        "generator_manifest_files": {
            "klean_export.py": generator_manifest["exporter_sha256"],
            "klean.py": generator_manifest["klean_py_sha256"],
        },
        "all_file_hashes_match": (
            producer_observed
            == producer_manifest["files"]
            == {
                "klean_export.py": generator_manifest["exporter_sha256"],
                "klean.py": generator_manifest["klean_py_sha256"],
            }
        ),
        "audit_input_image_id_from_producer_path": recorded_image_id,
        "source_manifest_image_id": producer_manifest["generator_image_id"],
        "generator_manifest_image_id": generator_manifest["provenance"][
            "generator_image_id"
        ],
        "all_image_ids_match": (
            recorded_image_id
            == producer_manifest["generator_image_id"]
            == generator_manifest["provenance"]["generator_image_id"]
        ),
        "producer_tree_hash_check": hash_checks[
            "generation_producer_sources_sha256"
        ],
    },
)

preflight = check_generation(
    STAGE1,
    DISCOVERY,
    GENERATION,
    toolchain_lock=Path("/reference/klean-toolchain.lock.json"),
)
dump("stage4-preflight-rerun.json", preflight)

obligation_map = json.loads(
    (GENERATED / "obligation-map.json").read_text()
)
domain_ids = [
    rule["source_rule_id"]
    for rule in discovery["rules"]
    if rule["classification"] == "DOMAIN_LEMMA"
]
obligation_ids = [
    obligation["source_rule_id"]
    for obligation in obligation_map["obligations"]
]
target = klean_export.target_statement(GENERATED)
dump(
    "stage4-obligation-and-target-check.json",
    {
        "independently_classified_domain_rule_ids": domain_ids,
        "generated_obligation_rule_ids": obligation_ids,
        "ordered_bijection": domain_ids == obligation_ids,
        "duplicates": len(obligation_ids) != len(set(obligation_ids)),
        "obligation_count": len(obligation_ids),
        "generator_manifest_obligation_count": generator_manifest[
            "obligation_count"
        ],
        "target_observed": target,
        "target_matches_generator_manifest": (
            target == generator_manifest["target"]
        ),
        "target_matches_audit_input": target == audit["target"],
        "target_definition_file_sha256": sha256_file(
            GENERATED / generator_manifest["target"]["file"]
        ),
    },
)

candidate_text = (CANDIDATE / "Proof.lean").read_text()
candidate_declarations = klean_export.lean_trust_declarations(
    CANDIDATE / "Proof.lean"
)
dump(
    "candidate-static-scan.json",
    {
        "candidate_trust_declarations": candidate_declarations,
        "forbidden_token_offsets": {
            token: [
                index
                for index in range(len(candidate_text))
                if candidate_text.startswith(token, index)
                and (
                    index == 0
                    or not (
                        candidate_text[index - 1].isalnum()
                        or candidate_text[index - 1] == "_"
                    )
                )
                and (
                    index + len(token) == len(candidate_text)
                    or not (
                        candidate_text[index + len(token)].isalnum()
                        or candidate_text[index + len(token)] == "_"
                    )
                )
            ]
            for token in ("sorry", "admit", "unsafe", "axiom", "opaque")
        },
        "proof_final_declaration_count": candidate_text.count(
            "theorem final :"
        ),
        "candidate_defines_target_statement": (
            "def targetStatement" in candidate_text
            or "opaque targetStatement" in candidate_text
            or "axiom targetStatement" in candidate_text
        ),
    },
)

base_target = (
    Path("/tmp/audit-work/21-rescale-to-unit-audit/Base")
    / generator_manifest["target"]["file"]
)
dump(
    "stage5-target-identity.json",
    {
        "base_target_sha256": sha256_file(base_target),
        "generated_target_sha256": sha256_file(
            GENERATED / generator_manifest["target"]["file"]
        ),
        "base_file_identical_to_generated": (
            base_target.read_bytes()
            == (
                GENERATED / generator_manifest["target"]["file"]
            ).read_bytes()
        ),
        "proof_final_expected_statement": generator_manifest["target"][
            "statement"
        ],
        "proof_final_uses_exact_expected_statement": (
            generator_manifest["target"]["statement"] in candidate_text
        ),
    },
)

